const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) adj[tok[2 + 3 * i]].push([tok[3 + 3 * i], tok[4 + 3 * i]]);
// binary min-heap of [dist, node]
const h = [];
const push = (x) => {
  h.push(x);
  let i = h.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (h[p][0] <= h[i][0]) break;
    [h[p], h[i]] = [h[i], h[p]];
    i = p;
  }
};
const pop = () => {
  const top = h[0], last = h.pop();
  if (h.length) {
    h[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let s = i;
      if (l < h.length && h[l][0] < h[s][0]) s = l;
      if (r < h.length && h[r][0] < h[s][0]) s = r;
      if (s === i) break;
      [h[s], h[i]] = [h[i], h[s]];
      i = s;
    }
  }
  return top;
};
const dist = new Array(n + 1).fill(Infinity);
dist[1] = 0;
push([0, 1]);
while (h.length) {
  const [d, u] = pop();
  if (d > dist[u]) continue;
  for (const [v, w] of adj[u]) {
    if (d + w < dist[v]) { dist[v] = d + w; push([dist[v], v]); }
  }
}
console.log(dist[n] === Infinity ? -1 : dist[n]);

